--[[

EzBuilder by Skira (https://github.com/solal0)
A simple tool that allows you to build using code

Usage example:
-- some features might not be available or work if you don't own certain tools or if you don't own a certain block/enough of them.

local builder = loadstring(game:HttpGet("https://raw.githubusercontent.com/solal0/Luau/refs/heads/main/Tools/210851291/Builder/builder.lua"))()

-- get a table of available blocks
local available = builder.getAvailable()
for name,amount in pairs(available) do
    print(name,amount)
end

-- if you want things done faster, consider changing the following values:
_G.EB_cooldown = 0.1 -- how much time to wait between each check (fallback to 0.1 if not specified)
_G.EB_loopFor = 12 -- number of checks done until an action is called a fail (fallback to 12 if not specified)
-- you can also set them with getenv().EB_cooldown = ... and getenv().EB_loopFor = ... but that might fail

-- create a block at specified CFrame
local success,block = builder.new("WoodBlock",game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame)

-- block is a table containing:
print(block.instance:GetFullName()) -- instance is the model, the block, you get it.
block.setColor(
    Color3.fromRGB(255,255,0) -- any Color3
)
block.setProperty(
    "Transparency", -- Any property name as it's called in the Property tool ui
    50, -- what to set the property to, true, false, 1, 100, ...
    true -- optional, false if not specified. If you want it on, consider checking the willDo function to know each property's max and min.
)
block.setSize(
    Vector3.new(10,10,10) -- any Vector3 (will override current size)
)
block.setPosition(
    block.instance.PrimaryPart.Position + Vector3.new(0,10,0) -- any Vector3 (will override current position)
)
block.setRotation(
    Vector3.new(0,math.rad(45),0) -- any Vector3 (will override current rotation)
)
block.delete()

]]--

local booleans = {
	["Anchored"] = true, ["Collision"] = true, ["CastShadow"] = true, -- Defaults
	["Aim"] = true, ["Crosshairs"] = true, ["Legacy"] = true, -- buttons, lever, ...
	["Additive"] = true, -- Display Block
	["And"] = true, ["Or"] = true, ["Xor"] = true, ["Not"] = true, -- Gate
	["Reverse rotation"] = true,
	["Show constraint"] = true,
	["Invertible"] = true,
	["Match rotation"] = true,
	["Reverse spin"] = true,
}

function willDo(property,value)
    if (property == "Transparency" and value >= 0 and value <= 100)
        or (property == "Density" and value >= 0.0001 and value <= 100)
        or (property == "Jet speed" and value >= 0)
        -- Jet force property exists but doing a call just increases it by 1 and goes back to 1 after reaching 5
        or (property == "Fuse time" and value >= 0 and value <= 60)
        or (property == "Jet speed" and value >= 0 and value <= 200)
        or (property == "Delay time" and value >= 0.05 and value <= 10)
        -- Servo torque property exists and is the same as Jet force
        or (property == "Servo speed" and value >= 0 and value <= 50)
        or (property == "Servo angle" and value >= 0 and value <= 180)
        or (property == "Piston length" and value >= 0.3 and value <= 10.5)
        or (property == "Piston speed" and value >= 1 and value <= 600)

        or (property == "Length" and value >= 2)
        or (property == "Angle limit" and value >= 0 and value <= 180)
        or (property == "Target length" and value >= 2)
        or (property == "Max length" and value >= 0.1)
        or (property == "Min length" and value >= 0)
        or (property == "Stiffness" and value >= 0 and value <= 250000)
        or (property == "Damping" and value >= 0 and value <= 250000)

        -- Wheel torque property exists and is the same as Jet force
        or (property == "Wheel speed" and value >= 0 and value <= 50)

        or (property == "Shrink head scale" and value >= 0.5 and value <= 1)
        or (property == "Shrink height scale" and value >= 0.5 and value <= 1)
        or (property == "Shrink width scale" and value >= 0.5 and value <= 1)
        or (property == "Shrink depth scale" and value >= 0.5 and value <= 1)

        or (booleans[property] and type(value) == "boolean") then return true end
    return false
end

